/* Custom footer for all report
 */
INSERT INTO `config` (`name`, `value`, `title`, `description`, `field_id`, `type_id`, `editable`) VALUES ('dio_achievement_report_schoolgrades_footer', '<dl class=\"key float-left\">\r\n    <dt>N</dt>\r\n    <dd>Not Achieved</dd>\r\n\r\n    <dt>A</dt>\r\n    <dd>Achieved</dd>\r\n\r\n    <dt>M</dt>\r\n    <dd>Achieved With Merit</dd>\r\n\r\n    <dt>E</dt>\r\n    <dd>Achieved With Excellence</dd>\r\n</dl>\r\n\r\n<dl class=\"key float-right\">\r\n    <dt>ABS</dt>\r\n    <dd>Absent</dd>\r\n\r\n    <dt>SNA</dt>\r\n    <dd>Standard Not Attempted</dd>\r\n\r\n    <dt>RNA</dt>\r\n    <dd>Result Not Yet Available</dd>\r\n</dl>\r\n\r\n<div class=\'clearfix\'></div>\r\n\r\n<p>\r\n    Further information about your results, reviews and reconsiderations,\r\n    endorsements, credit inclusion, and booklet return is available from\r\n    NZQA site on the <a href=\"http://www.nzqa.govt.nz/qualifications-standards/qualifications/ncea/ncea-results/results-publication/\">Results Publication Information</a>\r\n    page. You should also review the <a href=\"http://www.nzqa.govt.nz/qualifications-standards/qualifications/ncea/subjects/judgement-statements\">judgement statements</a>\r\n    (which include cut scores for Level 1 standards).\r\n</p>\r\n\r\n<p>\r\n    Further information about University entrance, Literacy and Numeracy\r\n    requirements is available on NZQA site <a href=\"http://www.nzqa.govt.nz/qualifications-standards/awards/university-entrance/\">University Entrance Requirements</a>.\r\n</p>', 'Diocesan Achievement Report SchoolGrades Custom Footer', 'Diocesan Achievement Report SchoolGrades Custom Footer', '8', '15', 'true');
UPDATE `config` SET `value` = '    <p>\r\n        This report details the academic achievement and progress to date.\r\n        Internal assessments are often ongoing and may not be finalised\r\n        until later in this term. The internal assessment grades that have\r\n        not been finalised will be in brackets e.g. [M].\r\n    </p>\r\n\r\n    <dl class=\"key float-left\">\r\n        <dt>N</dt>\r\n        <dd>Not Achieved</dd>\r\n\r\n        <dt>A</dt>\r\n        <dd>Achieved</dd>\r\n\r\n        <dt>M</dt>\r\n        <dd>Achieved With Merit</dd>\r\n\r\n        <dt>E</dt>\r\n        <dd>Achieved With Excellence</dd>\r\n\r\n        <dt>SNA</dt>\r\n        <dd>Standard Not Attempted</dd>\r\n    </dl>\r\n\r\n    <dl class=\"key float-right\">\r\n        <dt>[N]</dt>\r\n        <dd>Not Achieved progress grade</dd>\r\n\r\n        <dt>[A]</dt>\r\n        <dd>Achieved progress grade</dd>\r\n\r\n        <dt>[M]</dt>\r\n        <dd>Achieved With Merit progress grade</dd>\r\n\r\n        <dt>[E]</dt>\r\n        <dd>Achieved With Excellence progress grade</dd>\r\n    </dl>\r\n' WHERE `name` = 'dio_achievement_report_schoolgrades_footer';

INSERT INTO `config` (`name`, `value`, `title`, `description`, `field_id`, `type_id`, `editable`) VALUES ('dio_achievement_report_ib_footer', '<dl class=\"key float-left\">\r\n    <dt>N</dt>\r\n    <dd>Not Achieved</dd>\r\n\r\n    <dt>A</dt>\r\n    <dd>Achieved</dd>\r\n\r\n    <dt>M</dt>\r\n    <dd>Achieved With Merit</dd>\r\n\r\n    <dt>E</dt>\r\n    <dd>Achieved With Excellence</dd>\r\n</dl>\r\n\r\n<dl class=\"key float-right\">\r\n    <dt>ABS</dt>\r\n    <dd>Absent</dd>\r\n\r\n    <dt>SNA</dt>\r\n    <dd>Standard Not Attempted</dd>\r\n\r\n    <dt>RNA</dt>\r\n    <dd>Result Not Yet Available</dd>\r\n</dl>\r\n\r\n<div class=\'clearfix\'></div>\r\n\r\n<p>\r\n    Further information about your results, reviews and reconsiderations,\r\n    endorsements, credit inclusion, and booklet return is available from\r\n    NZQA site on the <a href=\"http://www.nzqa.govt.nz/qualifications-standards/qualifications/ncea/ncea-results/results-publication/\">Results Publication Information</a>\r\n    page. You should also review the <a href=\"http://www.nzqa.govt.nz/qualifications-standards/qualifications/ncea/subjects/judgement-statements\">judgement statements</a>\r\n    (which include cut scores for Level 1 standards).\r\n</p>\r\n\r\n<p>\r\n    Further information about University entrance, Literacy and Numeracy\r\n    requirements is available on NZQA site <a href=\"http://www.nzqa.govt.nz/qualifications-standards/awards/university-entrance/\">University Entrance Requirements</a>.\r\n</p>', 'Diocesan Achievement Report IB Custom Footer', 'Diocesan Achievement Report IB Custom Footer', '8', '15', 'true');
INSERT INTO `config` (`name`, `value`, `title`, `description`, `field_id`, `type_id`, `editable`) VALUES ('dio_achievement_report_ncea_footer', '<dl class=\"key float-left\">\r\n    <dt>N</dt>\r\n    <dd>Not Achieved</dd>\r\n\r\n    <dt>A</dt>\r\n    <dd>Achieved</dd>\r\n\r\n    <dt>M</dt>\r\n    <dd>Achieved With Merit</dd>\r\n\r\n    <dt>E</dt>\r\n    <dd>Achieved With Excellence</dd>\r\n</dl>\r\n\r\n<dl class=\"key float-right\">\r\n    <dt>ABS</dt>\r\n    <dd>Absent</dd>\r\n\r\n    <dt>SNA</dt>\r\n    <dd>Standard Not Attempted</dd>\r\n\r\n    <dt>RNA</dt>\r\n    <dd>Result Not Yet Available</dd>\r\n</dl>\r\n\r\n<div class=\'clearfix\'></div>\r\n\r\n<p>\r\n    Further information about your results, reviews and reconsiderations,\r\n    endorsements, credit inclusion, and booklet return is available from\r\n    NZQA site on the <a href=\"http://www.nzqa.govt.nz/qualifications-standards/qualifications/ncea/ncea-results/results-publication/\">Results Publication Information</a>\r\n    page. You should also review the <a href=\"http://www.nzqa.govt.nz/qualifications-standards/qualifications/ncea/subjects/judgement-statements\">judgement statements</a>\r\n    (which include cut scores for Level 1 standards).\r\n</p>\r\n\r\n<p>\r\n    Further information about University entrance, Literacy and Numeracy\r\n    requirements is available on NZQA site <a href=\"http://www.nzqa.govt.nz/qualifications-standards/awards/university-entrance/\">University Entrance Requirements</a>.\r\n</p>', 'Diocesan Achievement Report NCEA Custom Footer', 'Diocesan Achievement Report NCEA Custom Footer', '8', '15', 'true');